return (function (data, lib) {
  const y = data.cross['US 10Y yield'].map(r=>r[1]);
  const vix = data.cross['VIX'].map(r=>r[1]);
  const yz = lib.zscore(y);
  const vz = lib.zscore(vix);
  const techShock = 0.0;
  const shock = Math.max(-1, Math.min(1, 0.5*yz + 0.3*vz + techShock));
  const eq = lib.clamp(0.5 - 0.08*shock, 0.30, 0.70);
  const bond = lib.clamp(0.5 + 0.05*shock, 0.30, 0.70);
  return {spx:{h1:eq,close:eq}, ndx:{h1:eq,close:eq}, tlt:{h1:bond,close:bond}, boil:{h1:0.45,close:0.45}, kospi:{h1:0.5,close:0.5}};
})(data, lib);

return (function (data, lib) {
  const out = {};
  for (const k of ['spx','ndx','tlt','boil','kospi']) {
    const a = data.assets[k];
    if (!a || !a.h1 || a.h1.length < 13) { out[k] = {h1:0.5, close:0.5}; continue; }
    const h = a.h1.map(x => x[1]);
    const last = h[h.length-1], prev1 = h[h.length-2], prev2 = h[h.length-3];
    const mom = last - prev2;
    const rev = last - prev1;
    // short-horizon mean reversion: if last bar fell sharply vs prior bar, slight up bias
    const z = lib.clamp(-rev / (lib.std(lib.returns(h.slice(-24))) + 1e-9) * 0.06, -0.08, 0.08);
    out[k] = { h1: lib.clamp(0.5 + z, 0.2, 0.8), close: lib.clamp(0.5 - 0.5*z, 0.25, 0.75) };
  }
  return out;
})(data, lib);

return (function(data, lib){
  const a=data.assets, c=data.cross;
  const vix=c['VIX']||[], y=c['US 10Y yield']||[];
  function last(arr){return arr.length?arr[arr.length-1][1]:null;}
  const v=last(vix)||18, y10=last(y)||4.5;
  const shock=lib.logistic((v-18)/4 + (y10-4.8)*1.5);
  const out={};
  for(const k of ['spx','ndx','tlt','boil','kospi']){
    const d=a[k]&&a[k].daily? a[k].daily:[], h=a[k]&&a[k].h1? a[k].h1:[];
    const r=d.length>3? lib.returns(d.map(x=>x[1])):[];
    const mom=r.length>2? lib.mean(r.slice(-5)):0;
    const p_close=lib.clamp(0.5+mom*8-shock*0.08*(k==='tlt'?-1:1),0.05,0.95);
    out[k]={h1:lib.clamp(0.5-shock*0.04,0.05,0.95),close:p_close};
  }
  return out;
})(data, lib);

return (function(data, lib) {
 const ndx = data.assets.ndx.daily;
 const ret = lib.returns(ndx.map(d => d[1]));
 const momentum = ret.slice(-3).reduce((a,b)=>a+b, 0);
 const p_down = momentum < -0.02 ? 0.35 : 0.50;
 return {
 spx: { h1: p_down + 0.05, close: p_down },
 ndx: { h1: p_down, close: p_down - 0.02 },
 tlt: { h1: 1 - p_down + 0.1, close: 1 - p_down + 0.1 },
 boil: { h1: 0.50, close: 0.50 },
 kospi: { h1: p_down + 0.05, close: p_down + 0.05 }
 };
})(data, lib);

return (function(data, lib) {
 const kospiDaily = data.assets.kospi.daily;
 const ndxDaily = data.assets.ndx.daily;
 if (kospiDaily.length < 5) return { kospi: { close: 0.5 }, ndx: { close: 0.5 } };
 const kospiRet = lib.returns(kospiDaily.slice(-3));
 const ndxRet = lib.returns(ndxDaily.slice(-3));
 const kospiAvg = lib.mean(kospiRet);
 const ndxAvg = lib.mean(ndxRet);
 const p_kospi = kospiAvg < 0 ? 0.45 : 0.55;
 const p_ndx = ndxAvg > 0 ? 0.60 : 0.50;
 return { kospi: { close: p_kospi }, ndx: { close: p_ndx } };
})(data, lib);
